insert into public.lessons (id, course_id, data) values ('l_math_pv', 'c_math_num', $ml${"id":"l_math_pv","courseId":"c_math_num","subject":"Mathematics","level":"Primary 5","title":"Place Value","topic":"Place Value","difficulty":"easy","minutes":10,"order":0,"body":"## What is place value?\nThe value of a digit depends on its position in a number. In 4,352 the 4 is worth 4,000 because it is in the thousands place.\n\n- Ones, tens, hundreds, thousands, ten-thousands …\n- Each place is 10 times the place to its right.\n\n> Read big numbers in groups of three from the right: 3,405,120 is \"three million, four hundred and five thousand, one hundred and twenty\".","examples":[{"problem":"What is the value of 7 in 57,312?","steps":["Count places from the right: 2 is ones, 1 tens, 3 hundreds, 7 thousands.","So 7 is worth 7 × 1,000."],"answer":"7,000"},{"problem":"Write 30,000 + 400 + 6 as a number.","steps":["Put each part in its place: 3 ten-thousands, 0 thousands, 4 hundreds, 0 tens, 6 ones."],"answer":"30,406"}],"builtIn":true,"createdAt":1767225600000}$ml$::jsonb) on conflict (id) do nothing;
insert into public.lessons (id, course_id, data) values ('l_math_mul', 'c_math_num', $ml${"id":"l_math_mul","courseId":"c_math_num","subject":"Mathematics","level":"Primary 5","title":"Multiplication Strategies","topic":"Multiplication","difficulty":"easy","minutes":12,"order":1,"body":"## Multiplication is repeated addition\n4 × 6 means four groups of six: 6 + 6 + 6 + 6 = 24.\n\n## Handy strategies\n- Doubling: 8 × 7 is double 4 × 7 = double 28 = 56.\n- Splitting: 6 × 14 = 6 × 10 + 6 × 4 = 60 + 24 = 84.\n- Order does not matter: 3 × 9 = 9 × 3.\n\n> Learn your times tables up to 12 × 12 — they make every other topic faster.","examples":[{"problem":"Work out 9 × 13.","steps":["Split 13 into 10 + 3.","9 × 10 = 90 and 9 × 3 = 27.","Add: 90 + 27."],"answer":"117"}],"builtIn":true,"createdAt":1767225600000}$ml$::jsonb) on conflict (id) do nothing;
insert into public.lessons (id, course_id, data) values ('l_math_bodmas', 'c_math_num', $ml${"id":"l_math_bodmas","courseId":"c_math_num","subject":"Mathematics","level":"Primary 5","title":"Order of Operations (BODMAS)","topic":"Order of Operations","difficulty":"medium","minutes":12,"order":2,"body":"## BODMAS\nWhen a calculation has several operations, do them in this order:\n- Brackets\n- Orders (powers and roots)\n- Division and Multiplication (left to right)\n- Addition and Subtraction (left to right)\n\n> Division and multiplication have the same rank — work left to right. The same is true for addition and subtraction.","examples":[{"problem":"Calculate 3 + 4 × 2.","steps":["Multiplication first: 4 × 2 = 8.","Then add: 3 + 8."],"answer":"11"},{"problem":"Calculate (6 + 2) × 5 − 4.","steps":["Brackets: 6 + 2 = 8.","Multiply: 8 × 5 = 40.","Subtract: 40 − 4."],"answer":"36"}],"builtIn":true,"createdAt":1767225600000}$ml$::jsonb) on conflict (id) do nothing;
insert into public.lessons (id, course_id, data) values ('l_math_frac', 'c_math_frac', $ml${"id":"l_math_frac","courseId":"c_math_frac","subject":"Mathematics","level":"Primary 6","title":"Understanding Fractions","topic":"Fractions","difficulty":"medium","minutes":15,"order":3,"body":"## Parts of a whole\nA fraction like 3/4 means 3 parts out of 4 equal parts. The top number is the numerator; the bottom is the denominator.\n\n## Equivalent fractions\nMultiply or divide top and bottom by the same number: 1/2 = 2/4 = 4/8.\n\n## Adding fractions\n- Same denominator: add the numerators. 2/7 + 3/7 = 5/7.\n- Different denominators: first make them the same using the lowest common multiple.\n\n> Always simplify your final answer: 6/8 = 3/4.","examples":[{"problem":"Add 1/3 + 1/4.","steps":["LCM of 3 and 4 is 12.","1/3 = 4/12 and 1/4 = 3/12.","4/12 + 3/12 = 7/12."],"answer":"7/12"},{"problem":"Simplify 12/18.","steps":["The highest common factor of 12 and 18 is 6.","12 ÷ 6 = 2, 18 ÷ 6 = 3."],"answer":"2/3"}],"builtIn":true,"createdAt":1767225600000}$ml$::jsonb) on conflict (id) do nothing;
insert into public.lessons (id, course_id, data) values ('l_math_pct', 'c_math_frac', $ml${"id":"l_math_pct","courseId":"c_math_frac","subject":"Mathematics","level":"Primary 6","title":"Decimals & Percentages","topic":"Percentages","difficulty":"medium","minutes":12,"order":4,"body":"## Percent means \"out of 100\"\n25% = 25/100 = 0.25.\n\n- Fraction → percentage: multiply by 100. 3/5 × 100 = 60%.\n- Percentage of an amount: 20% of 150 = 0.2 × 150 = 30.\n\n> To find 10%, divide by 10. Then build other percentages from it: 30% = 3 × 10%.","examples":[{"problem":"Find 15% of 80.","steps":["10% of 80 = 8.","5% is half of 10% = 4.","15% = 8 + 4."],"answer":"12"}],"builtIn":true,"createdAt":1767225600000}$ml$::jsonb) on conflict (id) do nothing;
insert into public.lessons (id, course_id, data) values ('l_math_expr', 'c_math_alg', $ml${"id":"l_math_expr","courseId":"c_math_alg","subject":"Mathematics","level":"JSS 1","title":"Algebraic Expressions","topic":"Algebraic Expressions","difficulty":"medium","minutes":12,"order":5,"body":"## Letters stand for numbers\nIn 3x + 2, x is a variable. 3x means 3 × x.\n\n## Like terms\nOnly like terms can be added: 4a + 3a = 7a, but 4a + 3b stays as it is.\n\n> Substitution: if x = 5, then 3x + 2 = 3 × 5 + 2 = 17.","examples":[{"problem":"Simplify 5y + 2x − 3y + 4x.","steps":["Group like terms: (5y − 3y) + (2x + 4x).","2y + 6x."],"answer":"6x + 2y"}],"builtIn":true,"createdAt":1767225600000}$ml$::jsonb) on conflict (id) do nothing;
insert into public.lessons (id, course_id, data) values ('l_math_eq', 'c_math_alg', $ml${"id":"l_math_eq","courseId":"c_math_alg","subject":"Mathematics","level":"JSS 1","title":"Solving Linear Equations","topic":"Linear Equations","difficulty":"medium","minutes":15,"order":6,"body":"## Keep the balance\nAn equation is like a balanced scale. Whatever you do to one side, do to the other.\n\n- Undo addition by subtracting; undo multiplication by dividing.\n- Aim to get the variable alone on one side.\n\n> Check your answer by substituting it back into the original equation.","examples":[{"problem":"Solve 2x + 7 = 19.","steps":["Subtract 7 from both sides: 2x = 12.","Divide both sides by 2."],"answer":"x = 6"},{"problem":"Solve x/3 − 2 = 4.","steps":["Add 2 to both sides: x/3 = 6.","Multiply both sides by 3."],"answer":"x = 18"}],"builtIn":true,"createdAt":1767225600000}$ml$::jsonb) on conflict (id) do nothing;
insert into public.lessons (id, course_id, data) values ('l_math_area', 'c_math_geo', $ml${"id":"l_math_area","courseId":"c_math_geo","subject":"Mathematics","level":"JSS 2","title":"Perimeter & Area","topic":"Perimeter and Area","difficulty":"medium","minutes":15,"order":7,"body":"## Perimeter\nThe distance around a shape. Rectangle: P = 2(l + w).\n\n## Area\nThe space inside a shape, measured in square units.\n- Rectangle: A = l × w\n- Triangle: A = ½ × base × height\n- Circle: A = πr²\n\n> Perimeter is measured in cm or m; area in cm² or m². Don't mix them up.","examples":[{"problem":"A rectangle is 8 cm long and 5 cm wide. Find its area and perimeter.","steps":["Area = 8 × 5 = 40 cm².","Perimeter = 2(8 + 5) = 26 cm."],"answer":"40 cm² and 26 cm"},{"problem":"Find the area of a triangle with base 10 m and height 6 m.","steps":["A = ½ × 10 × 6."],"answer":"30 m²"}],"builtIn":true,"createdAt":1767225600000}$ml$::jsonb) on conflict (id) do nothing;
insert into public.lessons (id, course_id, data) values ('l_math_ang', 'c_math_geo', $ml${"id":"l_math_ang","courseId":"c_math_geo","subject":"Mathematics","level":"JSS 2","title":"Angles","topic":"Angles","difficulty":"medium","minutes":10,"order":8,"body":"## Types of angles\n- Acute: less than 90°\n- Right: exactly 90°\n- Obtuse: between 90° and 180°\n- Reflex: between 180° and 360°\n\n## Angle facts\n- Angles on a straight line add up to 180°.\n- Angles in a triangle add up to 180°.\n- Angles around a point add up to 360°.","examples":[{"problem":"Two angles of a triangle are 50° and 60°. Find the third.","steps":["Angles in a triangle sum to 180°.","180 − 50 − 60."],"answer":"70°"}],"builtIn":true,"createdAt":1767225600000}$ml$::jsonb) on conflict (id) do nothing;
insert into public.lessons (id, course_id, data) values ('l_eng_pos', 'c_eng_gram', $ml${"id":"l_eng_pos","courseId":"c_eng_gram","subject":"English","level":"Primary 5","title":"Parts of Speech","topic":"Parts of Speech","difficulty":"easy","minutes":12,"order":9,"body":"## The eight parts of speech\n- Noun: names a person, place, animal or thing (Ada, Lagos, goat, book).\n- Pronoun: replaces a noun (she, it, they).\n- Verb: an action or state (run, is, think).\n- Adjective: describes a noun (tall, blue).\n- Adverb: describes a verb, adjective or adverb (quickly, very).\n- Preposition: shows position or relationship (on, under, between).\n- Conjunction: joins words or clauses (and, but, because).\n- Interjection: shows strong feeling (Wow! Oh!).\n\n> Ask what job the word is doing in the sentence — the same word can be a noun in one sentence and a verb in another.","examples":[{"problem":"Identify the adverb: \"The children sang loudly.\"","steps":["\"sang\" is the verb.","Which word tells us how they sang?"],"answer":"loudly"}],"builtIn":true,"createdAt":1767225600000}$ml$::jsonb) on conflict (id) do nothing;
insert into public.lessons (id, course_id, data) values ('l_eng_tense', 'c_eng_gram', $ml${"id":"l_eng_tense","courseId":"c_eng_gram","subject":"English","level":"Primary 5","title":"Verb Tenses","topic":"Tenses","difficulty":"easy","minutes":10,"order":10,"body":"## Past, present and future\n- Past: I walked to school.\n- Present: I walk to school.\n- Future: I will walk to school.\n\n## Irregular verbs\nSome verbs change completely in the past tense: go → went, eat → ate, see → saw.\n\n> Keep the tense consistent within a paragraph unless the time really changes.","examples":[{"problem":"Change to the past tense: \"She writes a letter.\"","steps":["\"writes\" is present tense.","The past tense of write is wrote."],"answer":"She wrote a letter."}],"builtIn":true,"createdAt":1767225600000}$ml$::jsonb) on conflict (id) do nothing;
insert into public.lessons (id, course_id, data) values ('l_eng_sva', 'c_eng_gram', $ml${"id":"l_eng_sva","courseId":"c_eng_gram","subject":"English","level":"Primary 5","title":"Subject–Verb Agreement","topic":"Subject-Verb Agreement","difficulty":"medium","minutes":10,"order":11,"body":"## Singular subject → singular verb\n- The boy runs. The boys run.\n- Each of the students has a book.\n- Neither Tola nor Emeka is late.\n\n> Words between the subject and verb don't change the agreement: \"The box of pencils IS on the table.\"","examples":[{"problem":"Choose the correct verb: \"The list of names (is/are) long.\"","steps":["The subject is \"list\" (singular), not \"names\"."],"answer":"is"}],"builtIn":true,"createdAt":1767225600000}$ml$::jsonb) on conflict (id) do nothing;
insert into public.lessons (id, course_id, data) values ('l_eng_syn', 'c_eng_vocab', $ml${"id":"l_eng_syn","courseId":"c_eng_vocab","subject":"English","level":"Primary 6","title":"Synonyms & Antonyms","topic":"Vocabulary","difficulty":"easy","minutes":10,"order":12,"body":"## Synonyms\nWords with similar meanings: big – large, happy – joyful.\n\n## Antonyms\nWords with opposite meanings: hot – cold, ancient – modern.\n\n> Using synonyms makes your writing more interesting. Instead of repeating \"good\", try excellent, pleasant or helpful.","examples":[{"problem":"Give an antonym of \"generous\".","steps":["Generous means willing to give.","The opposite is unwilling to give."],"answer":"mean / selfish / stingy"}],"builtIn":true,"createdAt":1767225600000}$ml$::jsonb) on conflict (id) do nothing;
insert into public.lessons (id, course_id, data) values ('l_eng_spell', 'c_eng_vocab', $ml${"id":"l_eng_spell","courseId":"c_eng_vocab","subject":"English","level":"Primary 6","title":"Spelling Rules","topic":"Spelling","difficulty":"easy","minutes":10,"order":13,"body":"## Useful rules\n- \"i before e except after c\": believe, receive (but watch for exceptions like \"science\").\n- Words ending in consonant + y: change y to i before -es/-ed: carry → carries, carried.\n- Doubling: short vowel + one consonant → double before -ing: run → running, swim → swimming.\n\n> Commonly misspelt words: necessary, separate, definitely, environment, government.","examples":[{"problem":"Add -ing to \"begin\".","steps":["Stress is on the last syllable, short vowel, one final consonant.","Double the n."],"answer":"beginning"}],"builtIn":true,"createdAt":1767225600000}$ml$::jsonb) on conflict (id) do nothing;
insert into public.lessons (id, course_id, data) values ('l_eng_comp', 'c_eng_read', $ml${"id":"l_eng_comp","courseId":"c_eng_read","subject":"English","level":"JSS 1","title":"Reading for Meaning","topic":"Reading Comprehension","difficulty":"medium","minutes":15,"order":14,"body":"## Steps for comprehension\n- Skim the passage first to get the main idea.\n- Read the questions, then scan the passage for key words.\n- Answer in your own words unless asked to quote.\n\n## Sample passage\nAdaeze woke before sunrise. She fed the chickens, swept the compound and still reached school before the bell. Her teacher praised her for never being late, even though she lived the farthest away.\n\n> Main idea vs detail: the main idea is what the whole passage is about; details support it.","examples":[{"problem":"What is the main idea of the passage about Adaeze?","steps":["The passage lists her chores and that she is still on time.","The teacher praises her punctuality."],"answer":"Adaeze is hardworking and always punctual."}],"builtIn":true,"createdAt":1767225600000}$ml$::jsonb) on conflict (id) do nothing;
insert into public.lessons (id, course_id, data) values ('l_eng_punc', 'c_eng_punc', $ml${"id":"l_eng_punc","courseId":"c_eng_punc","subject":"English","level":"JSS 1","title":"Using Punctuation Correctly","topic":"Punctuation","difficulty":"easy","minutes":12,"order":15,"body":"## Common marks\n- Full stop (.) ends a statement.\n- Question mark (?) ends a direct question.\n- Comma (,) separates items in a list or parts of a sentence.\n- Apostrophe (') shows possession (Tunde's bag) or a missing letter (don't).\n- Exclamation mark (!) shows strong feeling.\n\n> \"its\" means belonging to it; \"it's\" means \"it is\". The dog wagged its tail. It's raining.","examples":[{"problem":"Punctuate: \"where is amakas pen\"","steps":["It is a question, so it ends with ?","The pen belongs to Amaka → Amaka's.","Start with a capital letter."],"answer":"Where is Amaka's pen?"}],"builtIn":true,"createdAt":1767225600000}$ml$::jsonb) on conflict (id) do nothing;
insert into public.lessons (id, course_id, data) values ('l_sci_living', 'c_sci_living', $ml${"id":"l_sci_living","courseId":"c_sci_living","subject":"Basic Science","level":"JSS 1","title":"Living and Non-Living Things","topic":"Living Things","difficulty":"easy","minutes":12,"order":16,"body":"## Characteristics of living things (MRS NERG)\n- Movement\n- Respiration\n- Sensitivity\n- Nutrition\n- Excretion\n- Reproduction\n- Growth\n\nNon-living things (stone, chair, water) do not show all of these characteristics.\n\n> A car moves and uses fuel, but it cannot grow or reproduce — so it is non-living.","examples":[{"problem":"Is a seed living or non-living? Explain.","steps":["A seed can grow into a plant when conditions are right.","It carries out slow respiration."],"answer":"Living (it is dormant, not dead)."}],"builtIn":true,"createdAt":1767225600000}$ml$::jsonb) on conflict (id) do nothing;
insert into public.lessons (id, course_id, data) values ('l_sci_cell', 'c_sci_living', $ml${"id":"l_sci_cell","courseId":"c_sci_living","subject":"Basic Science","level":"JSS 1","title":"The Cell","topic":"Cells","difficulty":"medium","minutes":15,"order":17,"body":"## Building blocks of life\nAll living things are made of cells.\n\n## Parts of a cell\n- Nucleus: controls the cell's activities.\n- Cytoplasm: jelly-like substance where reactions happen.\n- Cell membrane: controls what enters and leaves.\n- Plant cells also have a cell wall, a large vacuole and chloroplasts.\n\n> Chloroplasts contain chlorophyll, which traps sunlight for photosynthesis.","examples":[{"problem":"Name two structures found in plant cells but not in animal cells.","steps":["Compare the two lists of parts."],"answer":"Cell wall and chloroplasts"}],"builtIn":true,"createdAt":1767225600000}$ml$::jsonb) on conflict (id) do nothing;
insert into public.lessons (id, course_id, data) values ('l_sci_matter', 'c_sci_matter', $ml${"id":"l_sci_matter","courseId":"c_sci_matter","subject":"Basic Science","level":"JSS 1","title":"States of Matter","topic":"Matter","difficulty":"easy","minutes":12,"order":18,"body":"## Matter is anything that has mass and occupies space\n- Solid: fixed shape and volume (ice, wood).\n- Liquid: fixed volume, takes the shape of its container (water, oil).\n- Gas: no fixed shape or volume (air, steam).\n\n## Changes of state\n- Melting: solid → liquid; Freezing: liquid → solid.\n- Evaporation/boiling: liquid → gas; Condensation: gas → liquid.\n\n> Water boils at 100 °C and freezes at 0 °C at sea level.","examples":[{"problem":"What change of state happens when water droplets form on a cold bottle?","steps":["Water vapour in the air touches the cold surface.","Gas turns into liquid."],"answer":"Condensation"}],"builtIn":true,"createdAt":1767225600000}$ml$::jsonb) on conflict (id) do nothing;
insert into public.lessons (id, course_id, data) values ('l_sci_energy', 'c_sci_matter', $ml${"id":"l_sci_energy","courseId":"c_sci_matter","subject":"Basic Science","level":"JSS 1","title":"Forms of Energy","topic":"Energy","difficulty":"medium","minutes":12,"order":19,"body":"## Energy is the ability to do work\n- Heat (thermal), light, sound, electrical, chemical, mechanical (kinetic and potential).\n\n## Energy changes form\n- A torch: chemical (battery) → electrical → light.\n- A kettle: electrical → heat.\n\n> Energy cannot be created or destroyed — only changed from one form to another.","examples":[{"problem":"What energy change happens in a radio?","steps":["A radio uses electricity.","It produces sound."],"answer":"Electrical → sound"}],"builtIn":true,"createdAt":1767225600000}$ml$::jsonb) on conflict (id) do nothing;
insert into public.lessons (id, course_id, data) values ('l_sci_acid', 'c_sci_env', $ml${"id":"l_sci_acid","courseId":"c_sci_env","subject":"Basic Science","level":"JSS 2","title":"Acids and Bases","topic":"Acids and Bases","difficulty":"medium","minutes":15,"order":20,"body":"## Acids\nSour taste, turn blue litmus red. Examples: lemon juice, vinegar.\n\n## Bases (alkalis)\nBitter, soapy feel, turn red litmus blue. Examples: soap, baking soda solution.\n\n## The pH scale\n- pH below 7: acidic\n- pH 7: neutral (pure water)\n- pH above 7: basic\n\n> Never taste or touch unknown chemicals in the lab — use indicators instead.","examples":[{"problem":"A solution turns red litmus paper blue. Is it acidic or basic?","steps":["Bases turn red litmus blue."],"answer":"Basic (alkaline)"}],"builtIn":true,"createdAt":1767225600000}$ml$::jsonb) on conflict (id) do nothing;
insert into public.lessons (id, course_id, data) values ('l_sci_env', 'c_sci_env', $ml${"id":"l_sci_env","courseId":"c_sci_env","subject":"Basic Science","level":"JSS 2","title":"Our Environment","topic":"Environment","difficulty":"easy","minutes":10,"order":21,"body":"## The environment is everything around us\nIt includes living parts (plants, animals) and non-living parts (air, water, soil).\n\n## Problems and solutions\n- Pollution (air, water, land) → proper waste disposal, recycling.\n- Deforestation → planting trees.\n- Erosion → planting cover crops, building drainage.\n\n> Reduce, Reuse, Recycle.","examples":[{"problem":"Give one way to reduce land pollution in your school.","steps":["Think about waste."],"answer":"Use bins and sort waste for recycling."}],"builtIn":true,"createdAt":1767225600000}$ml$::jsonb) on conflict (id) do nothing;
insert into public.lessons (id, course_id, data) values ('l_cs_intro', 'c_cs_intro', $ml${"id":"l_cs_intro","courseId":"c_cs_intro","subject":"Computer Studies","level":"JSS 1","title":"What is a Computer?","topic":"Introduction to Computers","difficulty":"easy","minutes":10,"order":22,"body":"## Definition\nA computer is an electronic machine that accepts data (input), processes it, stores it and produces information (output).\n\n## The IPO cycle\n- Input: keyboard, mouse, scanner\n- Process: CPU (central processing unit)\n- Output: monitor, printer, speakers\n- Storage: hard disk, flash drive\n\n> Data is raw facts; information is processed data that has meaning.","examples":[{"problem":"Classify: keyboard, printer, CPU.","steps":["Which accepts data, which processes, which shows results?"],"answer":"Input, output, processing"}],"builtIn":true,"createdAt":1767225600000}$ml$::jsonb) on conflict (id) do nothing;
insert into public.lessons (id, course_id, data) values ('l_cs_hw', 'c_cs_intro', $ml${"id":"l_cs_hw","courseId":"c_cs_intro","subject":"Computer Studies","level":"JSS 1","title":"Hardware and Software","topic":"Hardware and Software","difficulty":"easy","minutes":12,"order":23,"body":"## Hardware\nThe physical parts you can touch: monitor, keyboard, system unit.\n\n## Software\nPrograms that tell the hardware what to do.\n- System software: operating systems like Windows, Linux, Android.\n- Application software: word processors, games, browsers.\n\n> Online safety: never share your password, and tell an adult about anything online that makes you uncomfortable.","examples":[{"problem":"Is a web browser hardware or software? What kind?","steps":["You cannot touch a browser.","It helps the user do a task."],"answer":"Software — application software"}],"builtIn":true,"createdAt":1767225600000}$ml$::jsonb) on conflict (id) do nothing;
